package reverse_compat

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"

	"github.com/boltun/server/internal/e2e"
)

type dartEnvelope struct {
	EnvelopeB64      string `json:"envelope_b64"`
	MsgID            string `json:"msg_id"`
	Plaintext        string `json:"plaintext"`
	SenderPubHex     string `json:"sender_pub_hex"`
	RecipientPrivHex string `json:"recipient_priv_hex"`
}

// TestOpenDartSealedEnvelope proves Go Open() accepts an envelope produced
// by the Dart implementation (reverse cross-language direction). The input
// file is generated by client/test/e2e_vectors_test.dart tooling and is
// committed under testdata/. Skip with a clear failure if absent so CI
// notices the missing artifact.
func TestOpenDartSealedEnvelope(t *testing.T) {
	b, err := os.ReadFile("testdata/dart_sealed_envelope.json")
	if err != nil {
		t.Fatalf("missing testdata/dart_sealed_envelope.json: %v", err)
	}
	var d dartEnvelope
	if err := json.Unmarshal(b, &d); err != nil {
		t.Fatal(err)
	}
	priv, err := hex.DecodeString(d.RecipientPrivHex)
	if err != nil {
		t.Fatal(err)
	}
	kp, err := e2e.KeyPairFromPrivate(priv)
	if err != nil {
		t.Fatal(err)
	}
	env, err := e2e.DecodeEnvelope(d.EnvelopeB64)
	if err != nil {
		t.Fatal(err)
	}
	spub, err := hex.DecodeString(d.SenderPubHex)
	if err != nil {
		t.Fatal(err)
	}
	var sp [32]byte
	copy(sp[:], spub)
	plain, err := e2e.Open(kp, env, d.MsgID, &sp)
	if err != nil {
		t.Fatalf("Go Open of Dart envelope failed: %v", err)
	}
	if string(plain) != d.Plaintext {
		t.Fatalf("plaintext mismatch: got %q want %q", plain, d.Plaintext)
	}
}
